// Graft the UrRide (transport) bundle onto each matching locale so that
// t("urride.…") resolves through the same lookup as every inline section.
// Only locales that already exist in TRANSLATIONS receive it.
for (const [locale, section] of Object.entries(URRIDE)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].urride = section;
  }
}

for (const [locale, section] of Object.entries(EXPLORE_SETTINGS_FIX)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].exploreSettingsFix = section;
  }
}

for (const [locale, section] of Object.entries(EXPLORE_PROFILE_FIX)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].exploreProfileFix = section;
  }
}

for (const [locale, section] of Object.entries(EXPLORE_MESSAGES_FIX)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].exploreMessagesFix = section;
  }
}

// Graft the saved-locations bundle shared by UrMall and UrRide.
for (const [locale, section] of Object.entries(ADDRESS_BOOK)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].addressBook = section;
  }
}

// Graft the states / districts (regional targeting) bundle.
for (const [locale, section] of Object.entries(REGIONS)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].regions = section;
  }
}

// Graft translations for UI text that previously lived directly in JSX.
for (const [locale, section] of Object.entries(UI_TRANSLATIONS)) {
  if (TRANSLATIONS[locale]) {
    TRANSLATIONS[locale].ui = section;
  }
}

// Only locales whose bundle is complete are offered in the UI and used for
// device-language auto-detection. The sw bundle above is a partial stub
// (common → importContacts only) and stays dormant until fully translated, at
// which point they are added back here. Keep this list in sync with the fully
// translated bundles in TRANSLATIONS.
